            let container = try decoder.container(keyedBy: CodingKeys.self)
            self.records = try container.decode([ProgramRecord].self, forKey: .records)
            self.serial = try container.decode(Int.self, forKey: .serial)
            guard 0 <= self.serial else { throw DecodingError.dataCorruptedError(forKey: .serial, in: container, debugDescription: "serial is at least 0, not \(self.serial)") }
        }
        private enum CodingKeys: String, CodingKey {
            case records
            case serial
        }
    }

    public struct Progress: Codable, Equatable, Sendable {
        public var progress: Int?
        public var state: ProgressState
        public init(progress: Int? = nil, state: ProgressState) {
            self.progress = progress
            self.state = state
        }
        public init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            self.progress = try container.decodeIfPresent(Int.self, forKey: .progress)
            self.state = try container.decode(ProgressState.self, forKey: .state)
            if let value = self.progress {
                guard 0 <= value, value <= 255 else { throw DecodingError.dataCorruptedError(forKey: .progress, in: container, debugDescription: "progress is 0...255, not \(value)") }
            }
        }
        private enum CodingKeys: String, CodingKey {
            case progress
            case state
        }
    }

    public enum ProgressState: String, Codable, Equatable, Sendable {
        case set
        case error
        case indeterminate
        case pause
    }

    public enum Remote: Codable, Equatable, Sendable {
        case terminal(RemoteTerminal)
        case agent(RemoteAgent)
        private enum Tag: String, CodingKey { case type = "type" }
        public init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: Tag.self)
            switch try container.decode(String.self, forKey: .type) {
            case "terminal": self = .terminal(try RemoteTerminal(from: decoder))
            case "agent": self = .agent(try RemoteAgent(from: decoder))
            case let other: throw DecodingError.dataCorruptedError(forKey: .type, in: container, debugDescription: "unknown Remote \(other)")
            }
        }
        public func encode(to encoder: Encoder) throws {
            var container = encoder.container(keyedBy: Tag.self)
            switch self {
            case .terminal(let value):
                try container.encode("terminal", forKey: .type)
                try value.encode(to: encoder)
            case .agent(let value):
                try container.encode("agent", forKey: .type)
                try value.encode(to: encoder)
            }
        }
    }

